package com.dayglance.app.launcher

import com.dayglance.app.data.CalendarRepository.CalEvent
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertSame
import org.junit.Test
import java.time.LocalDate

/**
 * The provider's own calendar read against the web layer's, through the shared
 * fixture (dayglance-ios/TestFixtures/launcherDeviceEvents.vectors.json, whose
 * expected rows are generated by src/utils/launcherDeviceEvents.fixture.test.js):
 * one event must be one row whichever side read it.
 */
class LauncherDeviceEventsTest {

    private val fixture = JSONObject(
        LauncherDeviceEventsTest::class.java.getResourceAsStream("/launcherDeviceEvents.vectors.json")!!.bufferedReader().readText()
    )

    private fun event(o: JSONObject) = CalEvent(
        id = o.getString("id"), title = o.getString("title"), start = o.getString("start"), end = o.getString("end"),
        allDay = o.getBoolean("allDay"), notes = o.getString("notes"), location = o.getString("location"),
        calendarId = o.getString("calendarId"), calendarName = o.getString("calendarName"), color = o.getString("color"),
    )

    private fun reader(events: JSONObject): (LocalDate) -> List<CalEvent> = { date ->
        val arr = events.optJSONArray(date.toString()) ?: JSONArray()
        (0 until arr.length()).map { event(arr.getJSONObject(it)) }
    }

    /**
     * The fixture's events as one range read returns them: each instance once, whatever
     * days it covers, and only those that touch the asked range. The fixture lists each
     * day's events as the provider does (by start, VTODOs last).
     */
    private fun rangeReader(events: JSONObject): (LocalDate, LocalDate) -> List<CalEvent> = { from, to ->
        val seen = HashSet<Pair<String, String>>()
        val out = ArrayList<CalEvent>()
        for (key in events.keys().asSequence().sorted()) {
            val arr = events.getJSONArray(key)
            for (i in 0 until arr.length()) {
                val e = event(arr.getJSONObject(i))
                if (e.end.take(10) < from.toString() || e.start.take(10) > to.toString()) continue
                if (seen.add(e.id to e.start)) out.add(e)
            }
        }
        // As the provider lists them: instances by start, then the VTODOs.
        out.sortedWith(compareBy<CalEvent>({ it.id.startsWith("task-") }, { it.start }))
    }

    /** Key order and number boxing aside, the same JSON. */
    private fun normalised(o: JSONObject): Map<String, Any?> = JSONObject(o.toString()).toMap()

    @Test
    fun `the restore keywords are the web layer's`() {
        val arr = fixture.getJSONArray("restoreKeywords")
        assertEquals((0 until arr.length()).map { arr.getString(it) }.toSet(), LauncherDeviceEvents.RESTORE_KEYWORDS)
    }

    @Test
    fun `every fixture case reads to the rows the snapshot builds`() {
        val cases = fixture.getJSONArray("cases")
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val config = LauncherDeviceEvents.config(JSONObject().put("deviceCalendar", c.getJSONObject("deviceCalendar")))!!
            val today = LocalDate.parse(c.getString("today"))
            val read = reader(c.getJSONObject("events"))
            val rows = LauncherDeviceEvents.rows(LauncherDeviceEvents.windowDates(today, config).map { it to read(it) }, config)
            val expected = c.getJSONArray("rows")
            assertEquals(c.getString("name"), (0 until expected.length()).map { normalised(expected.getJSONObject(it)) }, rows.map { normalised(it) })
        }
    }

    @Test
    fun `one range read over the window lists the same rows as a read of each day`() {
        val cases = fixture.getJSONArray("cases")
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val config = LauncherDeviceEvents.config(JSONObject().put("deviceCalendar", c.getJSONObject("deviceCalendar")))!!
            val dates = LauncherDeviceEvents.windowDates(LocalDate.parse(c.getString("today")), config)
            val events = rangeReader(c.getJSONObject("events"))(dates.first(), dates.last())
            val rows = LauncherDeviceEvents.rows(LauncherDeviceEvents.byDate(dates, events), config)
            val expected = c.getJSONArray("rows")
            assertEquals(c.getString("name"), (0 until expected.length()).map { normalised(expected.getJSONObject(it)) }, rows.map { normalised(it) })
        }
    }

    @Test
    fun `a range read's events are listed under every day they cover`() {
        fun ev(id: String, start: String, end: String, allDay: Boolean) =
            CalEvent(id, id, start, end, allDay, "", "", "1", "Cal", "#039BE5")
        val dates = (0..3).map { LocalDate.parse("2026-11-01").plusDays(it.toLong()) }
        val trip = ev("trip", "2026-10-30", "2026-11-02", true)
        val late = ev("late", "2026-11-02T23:00:00", "2026-11-03T01:00:00", false)
        val lunch = ev("lunch", "2026-11-04T12:00:00", "2026-11-04T13:00:00", false)
        val listed = LauncherDeviceEvents.byDate(dates, listOf(trip, late, lunch)).associate { (d, es) -> d.toString() to es.map { it.id } }
        assertEquals(
            mapOf(
                "2026-11-01" to listOf("trip"),
                "2026-11-02" to listOf("trip", "late"),
                "2026-11-03" to listOf("late"),
                "2026-11-04" to listOf("lunch"),
            ),
            listed,
        )
    }

    @Test
    fun `a live read replaces the snapshot's native rows and keeps every other row`() {
        val c = fixture.getJSONArray("cases").getJSONObject(0)
        val snapshot = JSONObject()
            .put("version", 1)
            .put("tasks", JSONArray()
                .put(JSONObject().put("id", "t1").put("native", false))
                .put(JSONObject().put("id", "native-cal-stale-2026-10-21").put("native", true)))
            .put("deviceCalendar", c.getJSONObject("deviceCalendar"))
        val out = JSONObject(LauncherDeviceEvents.withLiveEvents(snapshot.toString(), LocalDate.parse("2026-10-21"), rangeReader(c.getJSONObject("events"))))
        val tasks = out.getJSONArray("tasks")
        val ids = (0 until tasks.length()).map { tasks.getJSONObject(it).getString("id") }
        assertEquals("t1", ids.first())
        assertEquals(false, "native-cal-stale-2026-10-21" in ids)
        assertEquals(c.getJSONArray("rows").length() + 1, ids.size)
    }

    @Test
    fun `a snapshot without the block, or one that does not parse, is served as it is`() {
        val plain = """{"version":1,"tasks":[{"id":"native-cal-1-2026-10-21","native":true}]}"""
        assertSame(plain, LauncherDeviceEvents.withLiveEvents(plain, LocalDate.parse("2026-10-21")) { _, _ -> error("not read") })
        assertSame("not json", LauncherDeviceEvents.withLiveEvents("not json", LocalDate.parse("2026-10-21")) { _, _ -> emptyList() })
    }

    /** nativeCalendar.test.js holds nativeEventDuration to the same values (#2278). */
    @Test
    fun `an event's duration runs from its full start to its full end, within a day`() {
        assertEquals(120, LauncherDeviceEvents.eventDuration("2026-06-22T23:00:00", "2026-06-23T01:00:00"))
        assertEquals(510, LauncherDeviceEvents.eventDuration("2026-06-22T22:00:00", "2026-06-23T06:30:00"))
        assertEquals(75, LauncherDeviceEvents.eventDuration("2026-12-31T23:30:00", "2027-01-01T00:45:00"))
        assertEquals(1440, LauncherDeviceEvents.eventDuration("2026-06-22T09:00:00", "2026-06-23T09:00:00"))
        assertEquals(1440, LauncherDeviceEvents.eventDuration("2026-06-22T09:00:00", "2026-06-24T09:00:00"))
        assertEquals(90, LauncherDeviceEvents.eventDuration("2026-06-22T09:00:00", "2026-06-22T10:30:00"))
        assertEquals(15, LauncherDeviceEvents.eventDuration("2026-06-22T09:00:00", "2026-06-22T09:05:00"))
        assertEquals(15, LauncherDeviceEvents.eventDuration("2026-06-22T09:00:00", "2026-06-21T09:00:00"))
        assertEquals(60, LauncherDeviceEvents.eventDuration("2026-06-22T09:00:00", ""))
        // Wall-clock across a DST change at midnight (America/Santiago's April and
        // September nights): the strings carry no zone, so 23:00-01:00 is 120.
        assertEquals(120, LauncherDeviceEvents.eventDuration("2026-04-04T23:00:00", "2026-04-05T01:00:00"))
        assertEquals(120, LauncherDeviceEvents.eventDuration("2026-09-05T23:00:00", "2026-09-06T01:00:00"))
    }

    @Test
    fun `energy is a restore keyword among the title's words, never a substring`() {
        assertEquals("restore", LauncherDeviceEvents.energy("Lunch with Sam"))
        assertEquals("restore", LauncherDeviceEvents.energy("#gym session"))
        assertEquals("effort", LauncherDeviceEvents.energy("Restaurant booking"))
    }
}
